//! Production, stage 6: INTSUM (24 h) and SITREP (6 h) per region (spec P3).
//!
//! A product is a template filled with computed facts; nothing is generated by a
//! language model. Wording follows the standards it cites:
//!   - event credibility in Admiralty words (STANAG 2511): 1 confirmed, 2 probably
//!     true, 3 possibly true, 4 doubtful, 5 improbable, 6 cannot be judged;
//!   - a PIR judgement carries a confidence level (ICD 203): high if a supporting
//!     event is credibility 1-2, moderate if 3, low otherwise.

use std::collections::HashMap;

use chrono::Duration;
use serde_json::Value;

use crate::collect::{pystr, sha};
use crate::cycle::SourceRow;
use crate::fmt::{Time, iso};
use crate::regions::Region;
use crate::schema::{Event, Obs, Product, Status};
use crate::store;

const WORDS: [&str; 6] = [
    "confirmed",
    "probably true",
    "possibly true",
    "doubtful",
    "improbable",
    "cannot be judged",
];

fn kind_word(k: &str) -> &str {
    match k {
        "explosions_remote_violence" => "strike or explosion",
        "battles" => "fighting",
        "violence_against_civilians" => "violence against civilians",
        "protests" => "protest",
        "riots" => "riot",
        "strategic_developments" => "strategic development",
        "air_raid_alert" => "air-raid alert",
        "maritime_incident" => "maritime incident",
        "airspace_activity" => "drone or missile track",
        "thermal_anomaly" => "thermal anomaly",
        "internet_outage" => "internet outage",
        k => k,
    }
}

/// Hours a product covers: INTSUM 24, SITREP 6.
pub const PERIOD: [(&str, i64); 2] = [("intsum", 24), ("sitrep", 6)];

pub fn period(kind: &str) -> i64 {
    PERIOD.iter().find(|p| p.0 == kind).map_or(24, |p| p.1)
}

pub fn confidence(best: i64) -> &'static str {
    if best <= 2 {
        "high"
    } else if best == 3 {
        "moderate"
    } else {
        "low"
    }
}

fn s(v: &Value) -> String {
    pystr(v)
}

fn ids(I: &[&Value]) -> String {
    I.iter().map(|i| s(&i["id"])).collect::<Vec<_>>().join(", ")
}

/// Product text (Markdown) for region r over the last period(kind) hours.
pub fn report(r: &Region, board: &[Value], sources: &[SourceRow], kind: &str, t: Time) -> String {
    let h = period(kind);
    let t0 = t - Duration::hours(h);
    let EV = store::view::<Event>();
    let mut E: Vec<&Event> = EV
        .iter()
        .filter(|e| e.region == r.id && e.t_end > t0 && e.kind != "thermal_anomaly")
        .collect();
    E.sort_by_key(|a| {
        (
            a.credibility,
            std::cmp::Reverse(a.observation_ids.len()),
            std::cmp::Reverse(a.t_end),
        )
    });
    E.truncate(12);
    let OV = store::view::<Obs>();
    let first: Vec<&String> = E.iter().map(|e| &e.observation_ids[0]).collect();
    let O: HashMap<&str, &Obs> = OV
        .iter()
        .filter(|x| first.contains(&&x.id))
        .map(|x| (x.id.as_str(), x))
        .collect();
    let SV = store::rows::<Status>();
    let mut hist: Vec<&Status> = SV.iter().filter(|x| x.region == r.id && x.t > t0).collect();
    hist.sort_by_key(|x| x.t);
    let f = |t: &Time, p: &str| t.format(p).to_string();
    let mut L = vec![
        format!("# {}: {}", kind.to_uppercase(), r.name),
        format!(
            "Period {} to {} UTC. Automated product of Open-Source-Watch from public sources; every judgement \
                 below is mechanical and needs analyst review.",
            f(&t0, "%Y-%m-%d %H:%M"),
            f(&t, "%Y-%m-%d %H:%M")
        ),
        String::new(),
        "## Bottom line".into(),
    ];
    let ind = |p: &Value| p["indicators"].as_array().cloned().unwrap_or_default();
    for p in board {
        let head = format!("- **{}** {}", s(&p["pir"]), s(&p["question"]));
        let I = ind(p);
        match p["status"].as_str() {
            Some("answered") => {
                let k: Vec<&Value> = I.iter().filter(|i| i["status"] == "triggered").collect();
                let grades: Vec<i64> = k
                    .iter()
                    .filter_map(|i| i["best_credibility"].as_i64())
                    .collect();
                let j = match grades.iter().min() {
                    Some(&g) => format!("{} confidence", confidence(g)),
                    None => "confidence not assessed (sampled AIS coverage)".into(),
                };
                L.push(format!(
                    "{head} Indicator threshold met ({}); {j}.",
                    ids(&k)
                ));
            }
            Some("gap") => L.push(format!("{head} Cannot be assessed: collection gap.")),
            _ if I.iter().all(|i| i["status"] == "observed") => L.push(format!(
                "{head} Reporting counts only; no calibrated alert threshold."
            )),
            _ => L.push(format!("{head} No indicator at threshold.")),
        }
    }
    L.extend([
        "".into(),
        "## Indicators".into(),
        "".into(),
        "| PIR | Indicator | Value | Thresholds | Status |".into(),
        "| --- | --- | --- | --- | --- |".into(),
    ]);
    for p in board {
        for i in ind(p) {
            let none = i["status"] == "no data";
            let (v, th) = match i["metric"].as_str() {
                Some("transit") => (
                    if none {
                        "no AIS data".into()
                    } else {
                        format!(
                            "{} observed AIS crossings, z {}",
                            s(&i["count"]),
                            s(&i["z"])
                        )
                    },
                    format!("z ≤ {} / {}", s(&i["watch_z"]), s(&i["trigger_z"])),
                ),
                Some("event_count") => (
                    format!("{} in {} h", s(&i["count"]), s(&i["window_h"])),
                    "not calibrated".into(),
                ),
                Some("gnss") => (
                    if none {
                        "no data".into()
                    } else {
                        format!(
                            "{} cells {} on {}",
                            s(&i["count"]),
                            s(&i["band"]),
                            s(&i["date"])
                        )
                    },
                    "none (descriptive)".into(),
                ),
                Some("official") => (
                    if none {
                        "no data".into()
                    } else {
                        format!(
                            "{} on {}, median {} over {}",
                            s(&i["count"]),
                            s(&i["date"]),
                            s(&i["median"]),
                            s(&i["n_prior"])
                        )
                    },
                    "none (a party's claim)".into(),
                ),
                _ => (
                    format!("{} in {} h", s(&i["count"]), s(&i["window_h"])),
                    format!("{} / {}", s(&i["watch"]), s(&i["trigger"])),
                ),
            };
            L.push(format!(
                "| {} | {} {} | {v} | {th} | {} |",
                s(&p["pir"]),
                s(&i["id"]),
                s(&i["name"]),
                s(&i["status"])
            ));
        }
    }
    let changes: Vec<&&Status> = hist
        .iter()
        .enumerate()
        .filter(|(k, x)| {
            *k == 0 || (&x.indicator, &x.status) != (&hist[k - 1].indicator, &hist[k - 1].status)
        })
        .map(|x| x.1)
        .collect();
    let (mut seen, mut moved): (HashMap<&str, &str>, Vec<String>) = (HashMap::new(), vec![]);
    for x in changes {
        if let Some(prev) = seen.get(x.indicator.as_str()).filter(|p| **p != x.status) {
            moved.push(format!(
                "- {} {}: {prev} → {}",
                f(&x.t, "%H:%M"),
                x.indicator,
                x.status
            ));
        }
        seen.insert(&x.indicator, &x.status);
    }
    if !moved.is_empty() {
        L.push(String::new());
        L.push("Status changes in the period:".into());
        L.extend(moved);
    }
    let H: Vec<&Value> = board
        .iter()
        .filter(|p| p["hypotheses"].as_array().is_some_and(|h| !h.is_empty()))
        .collect();
    if !H.is_empty() {
        L.extend(["".into(), "## Competing hypotheses (ACH)".into()]);
        for p in H {
            L.push(format!(
                "{}, ranked by inconsistent evidence (fewest first):",
                s(&p["pir"])
            ));
            for x in p["hypotheses"].as_array().unwrap() {
                let list = |k: &str| {
                    x[k].as_array()
                        .unwrap()
                        .iter()
                        .map(s)
                        .collect::<Vec<_>>()
                        .join(", ")
                };
                let bad = if list("inconsistent").is_empty() {
                    "none".into()
                } else {
                    list("inconsistent")
                };
                let un = if list("unassessed").is_empty() {
                    String::new()
                } else {
                    format!("; not assessed: {}", list("unassessed"))
                };
                L.push(format!(
                    "- {} {}: inconsistent {bad}{un}",
                    s(&x["id"]),
                    s(&x["text"])
                ));
            }
        }
    }
    L.extend(["".into(), "## Significant events".into()]);
    for e in &E {
        let o = O.get(e.observation_ids[0].as_str());
        let place = o
            .and_then(|o| o.names.first().cloned())
            .unwrap_or_else(|| format!("{:.2}, {:.2}", e.lat, e.lon));
        let text: String = o
            .map_or("", |o| o.text_en.as_str())
            .chars()
            .take(160)
            .collect();
        L.push(format!(
            "- {} {} near {place}: {} ({} reports, {} independent A/B sources). {text}",
            f(&e.t_end, "%d %H:%M"),
            kind_word(&e.kind),
            WORDS[e.credibility as usize - 1],
            e.observation_ids.len(),
            e.n_independent
        ));
    }
    if E.is_empty() {
        L.push("- None in the period.".into());
    }
    let bad: Vec<&SourceRow> = sources.iter().filter(|s| s.health != "ok").collect();
    L.extend([
        "".into(),
        "## Collection".into(),
        format!(
            "{} of {} sources healthy.{}",
            sources.len() - bad.len(),
            sources.len(),
            if bad.is_empty() {
                String::new()
            } else {
                format!(
                    " Not healthy: {}.",
                    bad.iter()
                        .map(|s| format!("{} ({})", s.id, s.health))
                        .collect::<Vec<_>>()
                        .join(", ")
                )
            }
        ),
    ]);
    if !r.link.is_empty() {
        L.extend(["".into(), "## Related analysis".into()]);
        L.extend(
            r.link
                .iter()
                .map(|x| format!("- [{}]({}): {}", x.title, x.url, x.note)),
        );
    }
    L.join("\n") + "\n"
}

pub fn product(r: &Region, kind: &str, text: String, t: Time) -> Product {
    Product {
        id: sha(&format!("{}\0{kind}\0{}", r.id, iso(&t)), 32),
        region: r.id.clone(),
        kind: kind.into(),
        t,
        period_h: period(kind) as i16,
        text,
    }
}
